// enum for what type of medal an athlete wins

public class numbers {

   private static class number_t {
      String row[];
      number_t ( String row0, 
                 String row1, 
                 String row2, 
                 String row3, 
                 String row4 ) {
         row = new String[5];
         row[0] = row0;
         row[1] = row1;
         row[2] = row2;
         row[3] = row3;
         row[4] = row4;
      }
      public String getRow ( int i ) {
         return row[i];
      }
   }

   public static void main (String args[]) throws IOException {

      number_t numbers[] = new number_t[10];
      numbers[0] = new number_t ( "00000",
                                  "0   0",
                                  "0   0",
                                  "0   0",
                                  "00000" );
      numbers[1] = new number_t ( "  1  ",
                                  " 11  ",
                                  "  1  ",
                                  "  1  ",
                                  "11111" );
      numbers[2] = new number_t ( "22222",
                                  "    2",
                                  "22222",
                                  "2    ",
                                  "22222" );
      numbers[3] = new number_t ( "33333",
                                  "    3",
                                  "  333",
                                  "    3",
                                  "33333" );
      numbers[4] = new number_t ( "4   4",
                                  "4   4",
                                  "44444",
                                  "    4",
                                  "    4" );
      numbers[5] = new number_t ( "55555",
                                  "5    ",
                                  "55555",
                                  "    5",
                                  "55555" );
      numbers[6] = new number_t ( "66666",
                                  "6    ",
                                  "66666",
                                  "6   6",
                                  "66666" );
      numbers[7] = new number_t ( "77777",
                                  "    7",
                                  "    7",
                                  "    7",
                                  "    7" );
      numbers[8] = new number_t ( "88888",
                                  "8   8",
                                  "88888",
                                  "8   8",
                                  "88888" );
      numbers[9] = new number_t ( "99999",
                                  "9   9",
                                  "99999",
                                  "    9",
                                  "99999" );

      Scanner infile = new Scanner( new File("numbers.in") );

      int numDataSets = infile.nextInt(); infile.nextLine();

      // process the data sets
      String myNumber;
      for (int d = 0; d < numDataSets; d++) {

         myNumber = infile.nextLine();

         for (int row=0; row<5; row++) {
            for (int digit=0; digit < myNumber.length(); digit++) {
               System.out.print(
                  numbers[myNumber.charAt(digit) - 48].getRow(row) + " ");
            }
            System.out.println();
         }
      }
   }
}

// UIL 2007 - District A Hands-On Programming Contest
//

import java.io.*;
import java.util.*;

public class gravity {
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("gravity.in") );

      int numDataSets = infile.nextInt(); infile.nextLine();

      // process the data sets
      for (int d = 0; d < numDataSets; d++) {

         String [] board = new String[10];
         int [] rowcount = new int[10];
         int [] colcount = new int[10];
         char direction;

         // read in the next data set
         for (int row=0; row < 10; row++) {
            board[row]=infile.nextLine();
         }
         direction = infile.nextLine().charAt(0);

         // count the number of rocks in each row and col
         for (int row=0; row < 10; row++) {
            for (int col=0; col < 10; col++) {
               if ( board[row].charAt(col) == '#' ) {
                  ++rowcount[row];
                  ++colcount[col];
               }
            }
         }

         // output the result
         System.out.println("Data Set #" + (d+1));
         for (int row=0; row < 10; row++) {
            for (int col=0; col < 10; col++) {
               switch (direction) {
                  case 'U':
                     if (colcount[col] > row) System.out.print("#");
                     else                     System.out.print(".");
                     break;
                  case 'D':
                     if (colcount[col] > (9-row)) System.out.print("#");
                     else                         System.out.print(".");
                     break;
                  case 'L':
                     if (rowcount[row] > col) System.out.print("#");
                     else                     System.out.print(".");
                     break;
                  case 'R':
                     if (rowcount[row] > (9-col)) System.out.print("#");
                     else                         System.out.print(".");
                     break;
               }
            }
            System.out.println("");
         }
      }
   }
}

// UIL 2007 - District A Hands-On Programming Contest
//

import java.io.*;
import java.util.*;

public class who {

   static String [] person = new String[100];
   static boolean [] [] knows = new boolean[100][100];
   static int numPeople = 0;

   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("who.in") );

      int numAssocs = new Integer(infile.next());
      int numTests  = new Integer(infile.next());
      infile.nextLine();

      for (int assoc = 0; assoc < numAssocs; assoc++) {
         addAssoc( infile.next(), infile.next());
         infile.nextLine();
      }

      for (int test = 0; test < numTests; test++) {
         printAssoc(infile.next(), infile.next());
         infile.nextLine(); 
      }
   }

   static void addAssoc ( String name1, String name2 ) {
      int src=-1;
      int target=-1;

      for (int i=0; i < numPeople; i++) {
         if (name1.equals(person[i])) src=i;
         if (name2.equals(person[i])) target=i;
      }

      if (src == -1) {
         person[numPeople] = new String(name1);
         src = numPeople;
         numPeople++;
      }

      if (target == -1) {
         person[numPeople] = new String(name2);
         target = numPeople;
         numPeople++;
      }

      knows[src][target] = true;
      knows[target][src] = true;

      // all-pairs shortest path (modified)
      for (int k=0; k<numPeople; k++) {
         for (int i=0; i<numPeople; i++) {
            for (int j=0; j<numPeople; j++) {
               if (knows[i][k] && knows[k][j]) {
                  knows[i][j] = knows[j][i] = true;
               }
            }
         }
      }
   }

   static boolean isAssoc ( String name1, String name2 ) {
      int src=-1;
      int target=-1;

      for (int i=0; i < numPeople; i++) {
         if (name1.equals(person[i])) src=i;
         if (name2.equals(person[i])) target=i;
      }

      return knows[src][target];
   }

   static void printAssoc ( String name1, String name2 ) {
      if ( isAssoc (name1, name2) ) {
         System.out.println(name1 + " is connected to " + name2);
      } else {
         System.out.println(name1 + " has no known connection to " + name2);
      }
   }
}

// UIL 2007 - District A Hands-On Programming Contest
//

import java.io.*;
import java.util.*;

public class fence {

   static final int UP = 0;
   static final int DOWN = 1;
   static final int LEFT = 2;
   static final int RIGHT = 3;

   static final int EMPTY = 0;
   static final int POST  = 1;
   static final int FENCE = 2;

   static int [] [] field = new int[101][101];

   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("fence.in") );

      int numDataSets = infile.nextInt(); infile.nextLine();

      // process the data sets
      for (int d = 0; d < numDataSets; d++) {

         int numMoves = infile.nextInt(); infile.nextLine();
         int totalLength = 0;
         int direction = UP;
         int row, col;

         // clear the field
         for (row = 1; row < 101; row++) {
            for (col = 1; col < 101; col++) {
               field[row][col]=EMPTY;
            }
         }

         row = col = 50;

         // draw the fence
         for (int move=0; move < numMoves; move++) {
            int movelen = infile.nextInt();
            char turn = 'L';
            if (move < numMoves-1) turn = infile.next().charAt(0);

            totalLength += movelen;

            field[row][col] = POST;
            switch (direction) {
               case UP:
                  for (int i=0; i<movelen; i++) {
                     field[row-1][col] = FENCE;
                     row-=2;
                  }
                  if (turn == 'L') direction = LEFT;
                  else             direction = RIGHT;
                  break;
               case DOWN:
                  for (int i=0; i<movelen; i++) {
                    field[row+1][col] = FENCE;
                    row+=2;
                  }
                  if (turn == 'L') direction = RIGHT;
                  else             direction = LEFT;
                  break;
               case LEFT:
                  for (int i=0; i<movelen; i++) {
                    field[row][col-1] = FENCE;
                    col-=2;
                  }
                  if (turn == 'L') direction = DOWN;
                  else             direction = UP;
                  break;
               case RIGHT:
                  for (int i=0; i<movelen; i++) {
                    field[row][col+1] = FENCE;
                    col+=2;
                  }
                  if (turn == 'L') direction = UP;
                  else             direction = DOWN;
                  break;
            }
         } 
         int area = 0;

         for (row = 1; row < 101; row+=2) {
            boolean infence = false;
            for (col = 0; col < 101; col+=2) {
               if (field[row][col] == FENCE) infence = !infence;
               if (infence) area++;
            }
         }

         System.out.print("Fence " + (d+1));
         System.out.print(" is " + totalLength + " yards long");
         System.out.print(" and encloses an area of " + area);
         System.out.println(" square yard(s).");

      }
   }
}
